import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.1C62pOns.js";const n="/pro-agent-hub-installer/capturas/es/mcp-externo.png",s="/pro-agent-hub-installer/capturas/es/mcp-proprio.png",g=JSON.parse('{"title":"Servicios MCP","description":"","frontmatter":{},"headers":[],"relativePath":"es/interface/mcp.md","filePath":"es/interface/mcp.md","lastUpdated":1787856241000}'),i={name:"es/interface/mcp.md"};function l(c,e,p,u,d,m){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="servicios-mcp" tabindex="-1">Servicios MCP <a class="header-anchor" href="#servicios-mcp" aria-label="Permalink to &quot;Servicios MCP&quot;">​</a></h1><p><strong>MCP</strong> (Model Context Protocol) es el estándar por el que un agente gana herramientas que no venían de fábrica. La pantalla registra dos tipos bastante distintos, y la elección se hace al crear:</p><ul><li><strong>Externo</strong> — un servidor MCP de un tercero, que consumes por URL.</li><li><strong>Propio</strong> — un servidor que <em>tú</em> escribes aquí, y que la plataforma publica.</li></ul><h2 id="externo" tabindex="-1">Externo <a class="header-anchor" href="#externo" aria-label="Permalink to &quot;Externo&quot;">​</a></h2><p><img src="'+n+'" alt="mcp-externo"></p><p>Basta el transporte, la URL y el tiempo límite. Nada se ejecuta en tu instalación — la plataforma solo habla con la dirección indicada.</p><p>Tras guardar, vincula el servicio a un agente en la pestaña Herramientas del agente.</p><h2 id="propio" tabindex="-1">Propio <a class="header-anchor" href="#propio" aria-label="Permalink to &quot;Propio&quot;">​</a></h2><p><img src="'+s+'" alt="mcp-proprio"></p><p>Aquí escribes las herramientas en Python y la plataforma levanta un servidor MCP para ellas, en un proceso aparte — un servicio MCP lento nunca bloquea una petición de la API.</p><h3 id="pestana-herramientas" tabindex="-1">Pestaña Herramientas <a class="header-anchor" href="#pestana-herramientas" aria-label="Permalink to &quot;Pestaña Herramientas&quot;">​</a></h3><p>Cada función de nivel superior se convierte en una herramienta. <strong>No escribas decorador ni ruta</strong>: la plataforma envuelve las funciones y monta el <code>register_tools</code> sola. El nombre, la firma y el docstring son el contrato que el modelo lee para decidir cuándo llamarla.</p><p>El ámbito trae <code>log()</code> y las operaciones de datos, sistema e integración — ver <a href="/pro-agent-hub-installer/es/funcoes/mcp_tools">MCP Propio</a>.</p><h3 id="pestana-auxiliares" tabindex="-1">Pestaña Auxiliares <a class="header-anchor" href="#pestana-auxiliares" aria-label="Permalink to &quot;Pestaña Auxiliares&quot;">​</a></h3><p>Código de apoyo: <code>import</code>, constantes y funciones compartidas. <strong>Nada de aquí se convierte en herramienta</strong>, aunque sea función de nivel superior. Es la separación entre &quot;lo que el modelo puede llamar&quot; y &quot;lo que tu código usa por dentro&quot;.</p><h3 id="pestana-autenticacion" tabindex="-1">Pestaña Autenticación <a class="header-anchor" href="#pestana-autenticacion" aria-label="Permalink to &quot;Pestaña Autenticación&quot;">​</a></h3><p>Tres llaves, y vale entender qué abre cada una:</p><ul><li><strong>Token fijo</strong> — un secreto que el llamante presenta. Es lo que entregas a un cliente fuera de la plataforma.</li><li><strong>Aceptar token de workflow</strong> — permite que workflows y planificadores de la propia instalación llamen al servicio sin token propio.</li><li><strong>Aceptar autenticación de usuario</strong> — permite que un usuario conectado llame, respetando sus grupos.</li></ul><p>Apagar las tres deja el servicio publicado e inalcanzable.</p><h3 id="pestana-versiones" tabindex="-1">Pestaña Versiones <a class="header-anchor" href="#pestana-versiones" aria-label="Permalink to &quot;Pestaña Versiones&quot;">​</a></h3><p>Cada guardado conserva una versión del código. Se puede comparar, restaurar y anotar una observación en cada una — el historial es lo que permite tocar un servicio que ya está en uso sin miedo.</p><h3 id="publicar" tabindex="-1">Publicar <a class="header-anchor" href="#publicar" aria-label="Permalink to &quot;Publicar&quot;">​</a></h3><p>El servicio propio solo entra en el aire tras publicarse, y corre en el <strong>puerto</strong> de su registro. Cada servicio tiene el suyo.</p><div class="warning custom-block"><p class="custom-block-title">La publicación se reconcilia, no es instantánea</p><p>El proceso que sirve los MCP compara periódicamente lo que está en el aire con lo que está en la base. Tras publicar, el endpoint aparece en segundos — no en el mismo instante del clic.</p></div><p><strong>Probar</strong> llama a la herramienta directamente desde la pantalla, sin pasar por un agente. Es la forma de separar &quot;la herramienta está mal&quot; de &quot;el modelo no la eligió&quot;.</p>',25)])])}const q=a(i,[["render",l]]);export{g as __pageData,q as default};
